"use client";
import { useRef } from 'react';
import gsap from 'gsap';
import { useGSAP } from '@gsap/react';
import SplitType from 'split-type';
import { ShieldCheck } from 'lucide-react';
import Link from 'next/link';

export default function Hero() {
  const containerRef = useRef<HTMLDivElement>(null);
  const headlineRef = useRef<HTMLHeadingElement>(null);
  const sublineRef = useRef<HTMLParagraphElement>(null);
  const imageFrameRef = useRef<HTMLDivElement>(null);
  const ctaRef = useRef<HTMLDivElement>(null);

  useGSAP(() => {
    if (!headlineRef.current || !sublineRef.current) return;

    // Split text setup
    const splitHeadline = new SplitType(headlineRef.current, { types: 'lines,words' });
    const splitSubline = new SplitType(sublineRef.current, { types: 'lines' });

    // Initial setup
    gsap.set(splitHeadline.words, { y: 30, opacity: 0 });
    gsap.set(splitSubline.lines, { y: 20, opacity: 0 });
    gsap.set(ctaRef.current, { y: 20, opacity: 0 });
    if (imageFrameRef.current) {
      gsap.set(imageFrameRef.current, { scale: 0.95, opacity: 0, y: 30 });
    }

    const tl = gsap.timeline({ delay: 0.2 });

    tl.to(splitHeadline.words, {
      y: 0,
      opacity: 1,
      duration: 1,
      stagger: 0.04,
      ease: 'power3.out',
    })
    .to(splitSubline.lines, {
      y: 0,
      opacity: 1,
      duration: 0.8,
      stagger: 0.08,
      ease: 'power3.out',
    }, "-=0.6")
    .to(ctaRef.current, {
      y: 0,
      opacity: 1,
      duration: 0.8,
      ease: 'power3.out',
    }, "-=0.5")
    .to(imageFrameRef.current, {
      scale: 1,
      opacity: 1,
      y: 0,
      duration: 1.2,
      ease: 'power3.out',
    }, "-=0.8");

    return () => {
      splitHeadline.revert();
      splitSubline.revert();
    };
  }, { scope: containerRef });

  return (
    <section 
      ref={containerRef}
      className="relative w-full bg-bg-main flex items-center pt-28 pb-12 lg:pt-32 lg:pb-16 overflow-hidden"
    >
      {/* Background Decorative Accents */}
      <div className="absolute top-1/4 left-[-10%] w-[500px] h-[500px] bg-accent/5 rounded-full blur-3xl pointer-events-none"></div>
      <div className="absolute bottom-10 right-[5%] w-[350px] h-[350px] bg-primary-dark/5 rounded-full blur-3xl pointer-events-none"></div>

      <div className="container mx-auto px-6 md:px-12 relative z-10 grid grid-cols-1 lg:grid-cols-12 gap-12 lg:gap-8 items-center">
        
        {/* Left Column: Text & CTA */}
        <div className="lg:col-span-7 xl:col-span-7">
          <h1 
            ref={headlineRef}
            className="text-primary-dark text-4xl md:text-5xl lg:text-6xl font-heading font-medium leading-[1.15] tracking-tight mb-6"
          >
            Saúde, ciência e <span className="text-accent italic font-normal">sensibilidade</span> para o cuidado integral da sua pele.
          </h1>
          
          <p 
            ref={sublineRef}
            className="text-secondary-dark/80 text-base md:text-lg max-w-xl font-body leading-relaxed mb-8"
          >
            Uma abordagem que concilia diagnóstico clínico preciso com estética consciente. Aqui, sua pele é cuidada em todos os aspectos, sem promessas irrealistas.
          </p>

          <div ref={ctaRef} className="flex flex-col sm:flex-row gap-4 sm:gap-6">
            <Link 
              href="/contato"
              className="group relative px-8 py-4 overflow-hidden bg-accent text-white font-body font-medium text-sm md:text-base tracking-wide transition-all text-center rounded-sm shadow-md shadow-accent/15"
            >
              <span className="relative z-10">Agendar Consulta</span>
              <div className="absolute inset-0 bg-primary-dark translate-y-[100%] group-hover:translate-y-0 transition-transform duration-300 ease-out z-0"></div>
            </Link>
            
            <Link 
              href="/sobre"
              className="px-8 py-4 bg-transparent text-primary-dark border border-primary-dark/20 font-body font-medium text-sm md:text-base tracking-wide hover:bg-primary-dark/5 transition-all text-center rounded-sm"
            >
              Conhecer o Dr. Omar
            </Link>
          </div>
        </div>

        {/* Right Column: Architectural Arch Image Frame */}
        <div className="lg:col-span-5 xl:col-span-5 flex justify-center lg:justify-end relative">
          <div 
            ref={imageFrameRef}
            className="relative w-full max-w-[380px] lg:max-w-[420px] aspect-[4/5] rounded-t-[180px] lg:rounded-t-[210px] rounded-b-2xl overflow-hidden shadow-2xl shadow-primary-dark/10 border-4 border-white"
          >
            <img 
              src="/Foto do dr.JPG" 
              alt="Dr. Omar Algazal - Dermatologista" 
              className="w-full h-full object-cover object-top"
            />
            {/* Subtle soft gradient at base */}
            <div className="absolute inset-0 bg-gradient-to-t from-primary-dark/40 via-transparent to-transparent"></div>
          </div>
        </div>

      </div>
    </section>
  );
}
